class TestNullNaN:
    def test_chart_null_x_renders(self):
        """Chart with null values in x-encoded column should skip those rows."""
        df = pl.DataFrame({"x": [1.0, None, 3.0], "y": [1.0, 2.0, 3.0]})
        svg = fr.Chart(df).mark_point().encode(x="x", y="y").show_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_chart_null_color_renders(self):
        """Chart with null values in a color encoding should render remaining rows."""
        df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [1.0, 2.0, 3.0], "c": ["a", None, "b"]})
        svg = fr.Chart(df).mark_point().encode(x="x", y="y", color="c").show_svg()
        assert "<svg" in svg

    def test_displot_all_null_x_does_not_crash(self):
        """displot on a column that is entirely null — degenerate but should not panic."""
        df = pl.DataFrame({"x": pl.Series([None, None, None], dtype=pl.Float64)})
        # May raise or produce empty svg, but must not panic/segfault
        try:
            svg = fr.displot(df, x="x").show_svg()
            assert "<svg" in svg
        except (ValueError, Exception):
            pass  # graceful error is acceptable


