class TestErrorContracts:
    def test_displot_invalid_kind_raises(self):
        """displot with unknown kind should raise ValueError with legible message."""
        df = pl.DataFrame({"x": [1.0, 2.0]})
        with pytest.raises(ValueError, match="kind"):
            fr.displot(df, x="x", kind="bogus")

    def test_catplot_invalid_kind_raises(self):
        """catplot with unknown kind should raise ValueError."""
        df = pl.DataFrame({"cat": ["a", "b"], "val": [1.0, 2.0]})
        with pytest.raises(ValueError, match="kind"):
            fr.catplot(df, x="cat", y="val", kind="bogus")

    def test_lmplot_invalid_method_raises(self):
        """lmplot with unknown method should raise ValueError."""
        df = pl.DataFrame({"x": [1.0, 2.0], "y": [3.0, 4.0]})
        with pytest.raises(ValueError, match="method"):
            fr.lmplot(df, x="x", y="y", method="bogus")

    def test_repeat_chart_no_axis_raises(self):
        """RepeatChart with no row/column/layer raises ValueError."""
        df = pl.DataFrame({"a": [1.0]})
        base = fr.Chart(df).mark_point().encode(x="a")
        with pytest.raises(ValueError):
            fr.RepeatChart(base)

    def test_heatmap_no_numeric_columns_raises(self):
        """heatmap on a DataFrame with no numeric columns raises ValueError."""
        df = pl.DataFrame({"a": ["x", "y", "z"], "b": ["p", "q", "r"]})
        with pytest.raises(ValueError, match="numeric"):
            fr.heatmap(df)


# ===========================================================================
# Section 9: Spec round-trip and contract pins
# ===========================================================================


class TestSpecContracts:
    def test_to_spec_json_round_trip_preserves_mark(self, small_df):
        """to_spec → to_json → from_json should preserve mark field."""
        spec = fr.Chart(small_df).mark_point().encode(x="x", y="y").to_spec()
        j = spec.to_json()
        from ferrum import ChartSpec

        spec2 = ChartSpec.from_json(j)
        d = json.loads(spec2.to_json())
        assert d["mark"] == "point"

    def test_svg_viewbox_is_not_empty(self, small_df):
        """SVG output should contain a non-empty viewBox attribute."""
        svg = fr.Chart(small_df).mark_point().encode(x="x", y="y").show_svg()
        assert 'viewBox="' in svg

    def test_chart_immutable_fluent_chain(self, small_df):
        """Each fluent method returns a new Chart; original is unchanged."""
        base = fr.Chart(small_df).mark_point()
        encoded = base.encode(x="x", y="y")
        assert "x" not in base._encoding
        assert "x" in encoded._encoding

    def test_layered_chart_spec_has_layers_key(self, small_df):
        """Layered chart to_spec should have 'layers' in JSON."""
        c1 = fr.Chart(small_df).mark_point().encode(x="x", y="y")
        c2 = fr.Chart(small_df).mark_line().encode(x="x", y="y")
        layered = c1 + c2
        d = json.loads(layered.to_spec().to_json())
        assert "layers" in d
        assert len(d["layers"]) >= 2


