class TestTypeBoundaries:
    def test_integer_columns_for_xy(self):
        """Integer columns in x/y should render as quantitative."""
        df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
        svg = fr.Chart(df).mark_bar().encode(x="x", y="y").show_svg()
        assert "<svg" in svg

    def test_boolean_color_column(self):
        """Boolean column as color encoding should not crash."""
        df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [1.0, 2.0, 3.0], "flag": [True, False, True]})
        svg = fr.Chart(df).mark_point().encode(x="x", y="y", color="flag").show_svg()
        assert "<svg" in svg

    def test_string_column_in_x_axis_renders(self):
        """String column on x axis renders as ordinal."""
        df = pl.DataFrame({"cat": ["apple", "banana", "cherry"], "val": [10.0, 20.0, 15.0]})
        svg = fr.Chart(df).mark_bar().encode(x="cat", y="val").show_svg()
        assert "<svg" in svg
